function copyTree(string $src,string $dst): void { if(is_file($src)){@mkdir(dirname($dst),0755,true);copy($src,$dst);return;} @mkdir($dst,0755,true); foreach(new DirectoryIterator($src) as $f){if($f->isDot())continue;copyTree($f->getPathname(),$dst.'/'.$f->getFilename());} }
